head.script:
// col2 값별 radio 그룹(cellGroupName): 1=radioAPP, 2=radiobbb, 3=radiocc, 그 외 text
scwin.getType = function (info) {
	var rowIndex = info.rowIndex;
	var colIndex = info.colIndex;
	var group = { "1": ["dynamic_radioaaa_", "radioAPP"], "2": ["dynamic_radio1bbb_", "radiobbb"], "3": ["dynamic_radio1cc_", "radiocc"] }[dataList1.getCellData(rowIndex, "col2")];
	if (group) {
		return {
			id: group[0] + rowIndex + "_" + colIndex,
			inputType: "radio",
			options: {
				cellGroupName: group[1],
				selectedIndex: "-1"
			}
		};
	}
	return { id: "dynamic_text" + rowIndex + "_" + colIndex, inputType: "text", options: {} };
};

scwin.onpageload = function () {
	var jsonData = [{ "col2": "1" }, { "col2": "1" }, { "col2": "2" }, { "col2": "2" }, { "col2": "2" }, { "col2": "2" }, { "col2": "3" }, { "col2": "3" }, { "col2": "4" }];
	dataList1.setJSON(jsonData);
};

scwin.checkVal1 = function () {
	return (document.getElementById('grd_cell_0_0') || document.getElementById('mf_grd_cell_0_0')).children[0].checked;
};
scwin.checkVal2 = function () {
	return (document.getElementById('grd_cell_2_0') || document.getElementById('mf_grd_cell_2_0')).children[0].checked;
};
